from itertools import permutations

# Define the attributes
people = ['Avery', 'Blake', 'Casey', 'Finley', 'Jordan']
colors = ['blue', 'green', 'orange', 'red', 'yellow']
pets = ['bird', 'dog', 'fish', 'horse', 'rabbit']
drinks = ['cocoa', 'coffee', 'milk', 'tea', 'water']
hobbies = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

def check_constraints(assignment):
    """Check if an assignment satisfies all constraints.
    assignment is a dict: house_number -> {person, color, pet, drink, hobby}
    """

    # Extract positions for easier checking
    houses = {i: assignment.get(i, {}) for i in range(1, 6)}

    # Clue 1: milk drinker immediately left of dog owner
    for i in range(1, 5):
        if houses[i].get('drink') == 'milk' and houses[i+1].get('pet') == 'dog':
            pass
        elif houses[i].get('drink') == 'milk' and houses[i+1].get('pet') != 'dog':
            return False

    # Clue 2: water drinker immediately left of bird owner
    for i in range(1, 5):
        if houses[i].get('drink') == 'water' and houses[i+1].get('pet') == 'bird':
            pass
        elif houses[i].get('drink') == 'water' and houses[i+1].get('pet') != 'bird':
            return False

    # Clue 3: hiking person in red house
    for i in range(1, 6):
        if houses[i].get('hobby') == 'hiking' and houses[i].get('color') != 'red':
            return False
        if houses[i].get('color') == 'red' and houses[i].get('hobby') != 'hiking':
            return False

    # Clue 4: orange house next to cocoa drinker
    for i in range(1, 6):
        if houses[i].get('color') == 'orange':
            neighbors = []
            if i > 1:
                neighbors.append(houses[i-1])
            if i < 5:
                neighbors.append(houses[i+1])
            if not any(n.get('drink') == 'cocoa' for n in neighbors):
                return False
        if houses[i].get('drink') == 'cocoa':
            neighbors = []
            if i > 1:
                neighbors.append(houses[i-1])
            if i < 5:
                neighbors.append(houses[i+1])
            if not any(n.get('color') == 'orange' for n in neighbors):
                return False

    # Clue 5: rabbit owner next to yellow house
    for i in range(1, 6):
        if houses[i].get('pet') == 'rabbit':
            neighbors = []
            if i > 1:
                neighbors.append(houses[i-1])
            if i < 5:
                neighbors.append(houses[i+1])
            if not any(n.get('color') == 'yellow' for n in neighbors):
                return False
        if houses[i].get('color') == 'yellow':
            neighbors = []
            if i > 1:
                neighbors.append(houses[i-1])
            if i < 5:
                neighbors.append(houses[i+1])
            if not any(n.get('pet') == 'rabbit' for n in neighbors):
                return False

    # Clue 6: yellow house is Finley
    for i in range(1, 6):
        if houses[i].get('color') == 'yellow' and houses[i].get('person') != 'Finley':
            return False
        if houses[i].get('person') == 'Finley' and houses[i].get('color') != 'yellow':
            return False

    # Clue 7: rowing immediately left of water drinker
    for i in range(1, 5):
        if houses[i].get('hobby') == 'rowing' and houses[i+1].get('drink') == 'water':
            pass
        elif houses[i].get('hobby') == 'rowing' and houses[i+1].get('drink') != 'water':
            return False

    # Clue 8: Jordan is rabbit owner
    for i in range(1, 6):
        if houses[i].get('person') == 'Jordan' and houses[i].get('pet') != 'rabbit':
            return False
        if houses[i].get('pet') == 'rabbit' and houses[i].get('person') != 'Jordan':
            return False

    # Clue 9: Blake does fencing
    for i in range(1, 6):
        if houses[i].get('person') == 'Blake' and houses[i].get('hobby') != 'fencing':
            return False
        if houses[i].get('hobby') == 'fencing' and houses[i].get('person') != 'Blake':
            return False

    # Clue 10: rabbit owner immediately left of rowing person
    for i in range(1, 5):
        if houses[i].get('pet') == 'rabbit' and houses[i+1].get('hobby') == 'rowing':
            pass
        elif houses[i].get('pet') == 'rabbit' and houses[i+1].get('hobby') != 'rowing':
            return False

    # Clue 11: Casey immediately left of blue house
    for i in range(1, 5):
        if houses[i].get('person') == 'Casey' and houses[i+1].get('color') == 'blue':
            pass
        elif houses[i].get('person') == 'Casey' and houses[i+1].get('color') != 'blue':
            return False

    # Clue 12: Jordan does chess
    for i in range(1, 6):
        if houses[i].get('person') == 'Jordan' and houses[i].get('hobby') != 'chess':
            return False
        if houses[i].get('hobby') == 'chess' and houses[i].get('person') != 'Jordan':
            return False

    # Clue 13: milk drinker immediately left of blue house
    for i in range(1, 5):
        if houses[i].get('drink') == 'milk' and houses[i+1].get('color') == 'blue':
            pass
        elif houses[i].get('drink') == 'milk' and houses[i+1].get('color') != 'blue':
            return False

    # Clue 14: horse owner immediately left of tea drinker
    for i in range(1, 5):
        if houses[i].get('pet') == 'horse' and houses[i+1].get('drink') == 'tea':
            pass
        elif houses[i].get('pet') == 'horse' and houses[i+1].get('drink') != 'tea':
            return False

    return True

# Generate and check all permutations
solutions = []

for people_perm in permutations(people):
    for color_perm in permutations(colors):
        for pet_perm in permutations(pets):
            for drink_perm in permutations(drinks):
                for hobby_perm in permutations(hobbies):
                    assignment = {}
                    for i in range(5):
                        assignment[i+1] = {
                            'person': people_perm[i],
                            'color': color_perm[i],
                            'pet': pet_perm[i],
                            'drink': drink_perm[i],
                            'hobby': hobby_perm[i]
                        }

                    if check_constraints(assignment):
                        solutions.append(assignment)

# Display solutions
print(f"Found {len(solutions)} solution(s)\n")

for sol_idx, solution in enumerate(solutions, 1):
    print(f"Solution {sol_idx}:")
    for i in range(1, 6):
        house = solution[i]
        print(f"  House {i}: {house['person']:8} | {house['color']:8} | {house['pet']:8} | {house['drink']:8} | {house['hobby']:8}")
    print()

# Extract answer
if solutions:
    for i in range(1, 6):
        if solutions[0][i]['hobby'] == 'fencing':
            print(f"The person who does fencing is: {solutions[0][i]['person']}")

